const item = $input.first().json;

const cleanDomain = item.jiraDomain.replace(/\/+$/, '');
const authHeader = 'Basic ' + Buffer.from(`${item.jiraEmail}:${item.jiraApiToken}`).toString('base64');

const endpointUrl = `${cleanDomain}/rest/api/2/user/assignable/search?project=${item.projectKey}&maxResults=50`;

return [{
  json: {
    ...item,
    cleanDomain,
    authHeader,
    endpointUrl,
    stage: 'AUTH_AND_ENDPOINT_PREPARED'
  }
}];

const item = $input.first().json;
const { endpointUrl, authHeader, projectKey } = item;

let rawUsers = [];
let isFallback = false;

try {
  const res = await fetch(endpointUrl, {
    method: 'GET',
    headers: {
      'Authorization': authHeader,
      'Accept': 'application/json'
    }
  });

  if (res.ok) {
    const data = await res.json();
    if (Array.isArray(data) && data.length > 0) {
      rawUsers = data;
    } else {
      isFallback = true;
    }
  } else {
    isFallback = true;
  }
} catch (err) {
  isFallback = true;
}

// Danh sách thành viên mẫu chuẩn (Demo Fallback) mô phỏng nhóm dự án
