const item = $input.first().json;
const rawUsers = item.rawUsers || [];

// Lọc bỏ tài khoản bot, addon hoặc tài khoản bị vô hiệu hóa
const filteredUsers = rawUsers.filter(u => {
  const isRealUser = u.accountType === 'atlassian' || !u.accountType;
  const isActive = u.active !== false;
  const notBotName = !String(u.displayName || '').toLowerCase().includes('bot') && 
                     !String(u.displayName || '').toLowerCase().includes('addon');
  return isRealUser && isActive && notBotName;
});

const excludedCount = rawUsers.length - filteredUsers.length;

return [{
  json: {
    ...item,
    filteredUsers,
    excludedCount,
    stage: 'USERS_FILTERED'
  }
}];

