const item = $input.first().json;
const members = item.standardMembers || [];

// Phân tích dung lượng công việc (Workload Index) và gán Role chuyên môn
const analyzedMembers = members.map((m, idx) => {
  const roles = [
    { role: 'Backend & Cloud Lead', capacity: 'Cao (Sẵn sàng nhận Task)', skills: ['Node.js', 'PostgreSQL', 'API Architecture'] },
    { role: 'Mobile & Fullstack Engineer', capacity: 'Trung bình', skills: ['React', 'GPS & Maps API', 'Mobile App'] },
    { role: 'DevOps & Automation Specialist', capacity: 'Cao (Sẵn sàng nhận Task)', skills: ['n8n', 'Jira Cloud Integration', 'Webhooks'] },
    { role: 'AI & Data Processing Engineer', capacity: 'Trung bình', skills: ['Gemini AI', 'Data Pipelines', 'Reporting Engine'] }
  ];
  const roleInfo = roles[idx % roles.length];

  return {
    ...m,
    assignedRole: roleInfo.role,
    capacityStatus: roleInfo.capacity,
    coreSkills: roleInfo.skills
  };
});

return [{
  json: {
    ...item,
    analyzedMembers,
    stage: 'WORKLOAD_ANALYZED'
  }
}];

const item = $input.first().json;
const members = item.analyzedMembers || [];

// AI Smart Assignment: Gợi ý phân công công việc thông minh dựa trên kỹ năng
const membersWithAiBadge = members.map(m => {
  let aiRecommendation = 'Đảm nhiệm các công việc kỹ thuật tổng quát';
  if (m.coreSkills.includes('GPS & Maps API')) {
    aiRecommendation = 'Khuyến nghị ưu tiên giao: Task Bản đồ GPS, Ghép cuốc xe & Định vị thời gian thực';
  } else if (m.coreSkills.includes('PostgreSQL')) {
    aiRecommendation = 'Khuyến nghị ưu tiên giao: Task Thiết kế CSDL, Xử lý Cổng thanh toán & Bảo mật Auth';
  } else if (m.coreSkills.includes('n8n')) {
    aiRecommendation = 'Khuyến nghị ưu tiên giao: Task Đồng bộ Webhook, Bắn thông báo tự động đa kênh';
  } else if (m.coreSkills.includes('Gemini AI')) {
    aiRecommendation = 'Khuyến nghị ưu tiên giao: Task Phân rã yêu cầu AI, Trích xuất báo cáo thống kê KPI';
  }

  return {
    ...m,
    aiSmartRecommendation: aiRecommendation,
    badgeLabel: `${m.displayName} (${m.assignedRole})`
  };
});

return [{
  json: {
    ...item,
    members: membersWithAiBadge,
    aiEngineVersion: 'Gemini-SmartAssign-v2',
    stage: 'AI_ASSIGNMENT_OPTIMIZED'
  }
}];

