const item = $input.first().json;

const auditLog = {
  event: 'JIRA_PROJECT_MEMBERS_SYNC',
  projectKey: item.projectKey,
  totalFetched: item.members.length,
  excludedBots: item.excludedCount,
  syncedAt: new Date().toISOString(),
  status: 'SUCCESS'
};

const notificationSummary = `[Jira Team Sync] Dự án ${item.projectKey} đã đồng bộ thành công ${item.members.length} thành viên hợp lệ từ Jira Cloud.`;

return [{
  json: {
    ...item,
    auditLog,
    notificationSummary,
    stage: 'AUDIT_RECORDED'
  }
}];
